import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Preserve dtypes for later reconstruction
    ts_dtypes = target_state.dtypes.to_dict()

    # Build initial per-order state dict from target_state
    state = {}
    for row in target_state.itertuples(index=False):
        oid = row.order_id
        state[oid] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": row.last_seq,
        }

    # Original last_seq snapshot (for replay guard) -- fixed, does not evolve during batch
    original_last_seq = {oid: s["last_seq"] for oid, s in state.items()}
    original_has_row = set(state.keys())

    # Dedupe events: distinct by seq (same seq delivered twice -> apply once)
    events = cdc_events.drop_duplicates(subset=["seq"], keep="first").copy()

    # Sort by seq ascending -- the only trustworthy ordering
    events = events.sort_values("seq", kind="mergesort")

    # Track last applied event's op per order, to determine tombstones at the end
    tombstone_seq = {}  # order_id -> seq of the D event that currently "stands" as last

    for row in events.itertuples(index=False):
        seq = row.seq
        oid = row.order_id
        op = row.op
        status = row.status
        amount = row.amount

        # Replay guard: based on ORIGINAL target_state row, not evolving state
        if oid in original_has_row and seq <= original_last_seq[oid]:
            continue

        if op in ("I", "U"):
            if oid in state:
                # update existing row
                state[oid]["status"] = status
                if op == "U" and pd.isna(amount):
                    # leave amount unchanged
                    pass
                else:
                    state[oid]["amount"] = amount
                state[oid]["last_seq"] = seq
            else:
                # create new row from scratch; amount taken as-is (NULL stays NULL)
                state[oid] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                }
            # last applied event for this order is now I/U -> not a tombstone anymore
            if oid in tombstone_seq:
                del tombstone_seq[oid]
        elif op == "D":
            if oid in state:
                del state[oid]
                tombstone_seq[oid] = seq
            # D for a missing order does nothing
        else:
            # unknown op -- ignore defensively
            continue

    # Build new_state output
    cols_ns = ["order_id", "status", "amount", "last_seq"]
    if len(state) > 0:
        new_state_rows = []
        for oid, s in state.items():
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": s["status"],
                    "amount": s["amount"],
                    "last_seq": s["last_seq"],
                }
            )
        new_state = pd.DataFrame(new_state_rows, columns=cols_ns)
    else:
        new_state = pd.DataFrame(columns=cols_ns)

    # Restore dtypes where sensible
    for col in ["order_id", "status", "amount", "last_seq"]:
        if col in ts_dtypes:
            try:
                new_state[col] = new_state[col].astype(ts_dtypes[col])
            except (ValueError, TypeError):
                # leave as-is if cast fails (e.g. due to NaN in int column)
                pass

    # Build tombstones output
    cols_tomb = ["order_id", "deleted_seq"]
    if len(tombstone_seq) > 0:
        tomb_rows = [
            {"order_id": oid, "deleted_seq": seq}
            for oid, seq in tombstone_seq.items()
        ]
        tombstones = pd.DataFrame(tomb_rows, columns=cols_tomb)
    else:
        tombstones = pd.DataFrame(columns=cols_tomb)

    # Restore dtypes for tombstones
    if "order_id" in ts_dtypes:
        try:
            tombstones["order_id"] = tombstones["order_id"].astype(ts_dtypes["order_id"])
        except (ValueError, TypeError):
            pass
    if "seq" in cdc_events.dtypes:
        try:
            tombstones["deleted_seq"] = tombstones["deleted_seq"].astype(cdc_events.dtypes["seq"])
        except (ValueError, TypeError):
            pass

    return {"new_state": new_state, "tombstones": tombstones}
